/// @title Module for flash loan from base asset pools
module protocol::flash_loan;

use std::type_name::{Self, TypeName};
use std::string::String;

use sui::coin::Coin;
use sui::clock::Clock;

use sui::event::emit;

use x_oracle::x_oracle::XOracle;
use x_oracle::user_oracle::get_price;

use protocol::app::{ProtocolApp, PackageCallerCap};
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::{Market, FlashLoan};
use protocol::value::coin_value;

public struct BorrowFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public struct RepayFlashLoanEvent has copy, drop {
    market: TypeName,
    borrower: address,
    asset: TypeName,
    amount: u64,
    fee: u64,
}

public fun borrow_flash_loan<MarketType, CoinType>(
    app: &ProtocolApp,
    cap: &PackageCallerCap,

    market: &mut Market<MarketType>,

    emode_group: u8,
    amount: u64,

    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    app.ensure_has_permission(object::id(cap), protocol::whitelist_admin::flash_loan());

    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @notice Repay flash loan to market
/// @dev This is the only method to repay flash loan, consume the flash loan hot potato object
/// @param version The version control object, contract version must match with this
/// @param market The market object, it contains base assets, and related protocol configs
/// @param coin The coin object to repay
/// @param loan The flash loan hot potato object, which contains the borrowed amount and fee
/// @ctx The SUI transaction context object
/// @custom:T The type of asset to repay
public fun repay_flash_loan<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, std::option::none(), ctx);
}

public fun repay_flash_loan_increase_referral_qualification<MarketType, CoinType>(
    app: &mut ProtocolApp,
    market: &mut Market<MarketType>,

    coin: Coin<CoinType>,
    loan: FlashLoan<MarketType, CoinType>,

    maybe_referral_code: Option<String>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,

    ctx: &mut TxContext,
) {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    // Emit the repay flash loan event
    emit(RepayFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        // amount is total repay coin amount
        amount: coin.value(),
        fee: loan.fee(),
    });

    let referral = app.referral_mut();
    track_referral(referral, ctx.sender(), loan.loan_amount(), type_name::with_defining_ids<CoinType>(), coin_decimals_registry, x_oracle, clock);
    let maybe_referral_code = referral.try_map_referral_code(ctx.sender(), maybe_referral_code);

    // Put the asset back to the market and consume the flash loan hot potato object
    market.repay_flash_loan(coin, loan, referral, maybe_referral_code, ctx);
}

fun borrow_flash_loan_inner<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let (coin, flash_loan) = market.borrow_flash_loan(emode_group, amount, ctx);

    // Emit the borrow flash loan event
    emit(BorrowFlashLoanEvent {
        market: type_name::with_defining_ids<MarketType>(),
        borrower: ctx.sender(),
        asset: type_name::with_defining_ids<CoinType>(),
        fee: flash_loan.fee(),
        amount,
    });

    // Return the borrowed coin object and the flash loan hot potato object
    (coin, flash_loan)
}

fun track_referral(
    referral: &mut protocol::referral::Referral,

    who: address,

    token_amount: u64,
    token_type: TypeName,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
) {
    if (referral.is_qualified_to_create_referral_code(who)) return;

    let decimals = coin_decimals_registry.decimals(token_type);
    // always use usd price
    let usd_price = get_price(x_oracle, token_type, x_oracle::x_oracle::usd(), clock);
    let collateral_value_usd = coin_value(usd_price, math::float::from(token_amount), decimals);

    referral.increase_usd_qualification(who, collateral_value_usd.floor());
}

#[test_only]
public fun borrow_flash_loan_against_group<MarketType, CoinType>(
    market: &mut Market<MarketType>,
    amount: u64,
    emode_group: u8,
    ctx: &mut TxContext,
): (Coin<CoinType>, FlashLoan<MarketType, CoinType>) {
    borrow_flash_loan_inner<MarketType, CoinType>(market, amount, emode_group, ctx)
}

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

